SourceCode.Declaration:
/// <summary>
/// Controller for CPI-driven Sales Order repricing.
/// Responsible for launching the SysOperation framework execution and
/// preventing accidental duplicate batch submissions.
/// </summary>
class METCPIRepricingController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Initializes the controller.
/// </summary>
protected void new()
{
    super(
        classStr(METCPIRepricingService),
        methodStr(METCPIRepricingService, process),
        SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Gets the caption displayed for the operation.
/// </summary>
/// <returns>
/// Operation caption.
/// </returns>
protected ClassDescription defaultCaption()
{
    return "@MET:CPISOPricing";
}

/// <summary>
/// Determines whether a CPI repricing batch job is already active.
/// </summary>
/// <remarks>
/// Checks for jobs that are currently executing or waiting to execute.
/// This reduces duplicate submissions but does not provide complete
/// concurrency protection. Exclusive execution should be enforced
/// within the service layer if required.
/// </remarks>
/// <returns>
/// True if an active batch job exists; otherwise false.
/// </returns>
private static boolean hasActiveBatchJob()
{
    Batch batch;

    select firstOnly RecId
        from batch
        where batch.ClassNumber == classNum(METCPIRepricingController)
           && (batch.Status == BatchStatus::Executing
            || batch.Status == BatchStatus::Waiting
            || batch.Status == BatchStatus::Ready);

    return batch.RecId != 0;
}

/// <summary>
/// Entry point for launching the CPI repricing process.
/// </summary>
/// <param name="_args">
/// Runtime arguments.
/// </param>
public static void main(Args _args)
{
    METCPIRepricingController controller =
        new METCPIRepricingController();

    controller.parmArgs(_args);

    if (METCPIRepricingController::hasActiveBatchJob())
    {
        warning("@MET:BatchWarningCPI");
        return;
    }

    if (Box::okCancel(
            "@MET:RepricingWarning",
            DialogButton::Cancel) == DialogButton::Ok)
    {
        controller.startOperation();
    }
}
